def is_cmd_enabled(group_id, cmd_key):
    """Check if a command is enabled for a group."""
    cmds = group_cmd_enabled.get(group_id, {})
    # Find default from CMD_DEFS
    for key, _, _, default in CMD_DEFS:
        if key == cmd_key:
            return cmds.get(cmd_key, default)
    return True

