def _help_cmd_row(cmd, desc, c):
    """Build a single command row: [cmd_code]  [description]"""
    return {
        "type": "box",
        "layout": "baseline",
        "spacing": "md",
        "paddingTop": "sm",
        "paddingBottom": "sm",
        "contents": [
            {
                "type": "text",
                "text": cmd,
                "size": "xs",
                "color": c["cmd_color"],
                "weight": "bold",
                "flex": 4,
                "wrap": False,
            },
            {
                "type": "text",
                "text": desc,
                "size": "xs",
                "color": c["desc_color"],
                "flex": 5,
                "wrap": True,
            },
        ],
    }


def _help_section(num, tag, name, items, lang):
    """Build one section: header row + divider + command rows."""
    c = _HELP_COLORS[lang]
    rows = []
    # Section header
    rows.append({
        "type": "box",
        "layout": "baseline",
        "spacing": "sm",
        "margin": "lg",
        "contents": [
            {
                "type": "text",
                "text": num + " / " + tag,
                "size": "xxs",
                "color": c["accent"],
                "weight": "bold",
                "flex": 0,
            },
            {
                "type": "text",
                "text": name,
                "size": "xs",
                "color": c["cmd_color"],
                "weight": "bold",
                "flex": 0,
                "margin": "md",
            },
            {"type": "filler"},
        ],
    })
    rows.append({
        "type": "separator",
        "color": c["divider"],
        "margin": "sm",
    })
    for i, (cmd, zh_desc, id_desc) in enumerate(items):
        desc = zh_desc if lang == "zh" else id_desc
        rows.append(_help_cmd_row(cmd, desc, c))
        if i < len(items) - 1:
            rows.append({"type": "separator", "color": c["divider"]})
    return rows


def _build_help_bubble(lang, is_admin=False):
    """Build one Flex bubble for the given language ('zh' or 'id').
    非管理員(is_admin=False)會自動跳過標 admin_only 的 section(III / ADMIN)。
    """
    c = _HELP_COLORS[lang]
    if lang == "zh":
        hdr_meta = "COMMAND REFERENCE · ZH-TW"
        hdr_title = "翻譯機器人"
        hdr_sub = "不鏽鋼棒線部"
