@app.route("/api/admin/groups/settings", methods=["POST"])
def api_admin_group_settings():
    if not check_manager_access("groups"):
        return jsonify({"error": "forbidden"}), 403
    data = request.get_json() or {}
    gid = data.get("group_id", "")
    if not gid:
        return jsonify({"error": "missing group_id"}), 400
    if "target_lang" in data:
        group_target_lang[gid] = data["target_lang"]
        # v3.10: 後台改單一目標語言時,清掉 group_target_langs 讓單一語言生效
        # (否則 get_group_target_langs 會優先讀 list,後台改的單一語言會被忽略)
        try:
            group_target_langs.pop(gid, None)
        except NameError:
            pass   # v310 ext not loaded yet
    if "translation_on" in data:
        group_settings[gid] = bool(data["translation_on"])
    if "image_on" in data:
        group_img_settings[gid] = bool(data["image_on"])
        # 開了自動翻譯就清掉 ask 旗標
        if bool(data["image_on"]):
            group_img_ask_settings.pop(gid, None)
    if "image_ask_mode" in data:
        # 詢問模式 = image_on=False AND image_ask_mode=True
        if bool(data["image_ask_mode"]):
            group_img_settings[gid] = False
            group_img_ask_settings[gid] = True
        else:
            group_img_ask_settings.pop(gid, None)
    if "voice_on" in data:
        group_audio_settings[gid] = bool(data["voice_on"])
    if "work_order_on" in data:
        group_wo_settings[gid] = bool(data["work_order_on"])
    if "cmd_toggle" in data:
        cmd_key = data["cmd_toggle"]
        cmd_val = bool(data.get("cmd_val", True))
        if gid not in group_cmd_enabled:
            group_cmd_enabled[gid] = {}
        group_cmd_enabled[gid][cmd_key] = cmd_val
    # v3.10: 多語廣播設定
    if "target_langs" in data and isinstance(data["target_langs"], list):
        try:
            set_group_target_langs(gid, data["target_langs"])
        except NameError:
            # v310 ext 還沒載入時的 fallback (這在 admin API 應該不會發生)
            valid = [l for l in data["target_langs"] if isinstance(l, str)]
            if valid:
                group_target_lang[gid] = valid[0]
    # v3.10: TTS 開關
    if "tts_on" in data:
        try:
            group_tts_settings[gid] = bool(data["tts_on"])
        except NameError:
            pass
    # v3.10: flex_v2 視覺升級開關 (單一 key)
    if "flex_v2_key" in data:
        _k = data["flex_v2_key"]
        _v = bool(data.get("flex_v2_val", False))
        try:
            set_flex_v2(gid, _k, _v)
        except NameError:
            pass
    # v3.10: 上下文記憶開關 (獨立於 flex,翻譯邏輯)
    if "conv_ctx" in data:
        try:
            set_conv_context_enabled(gid, bool(data["conv_ctx"]))
        except NameError:
            pass
    # v3.9.46: force=True 同步寫盤
    save_settings(force=True)
    return jsonify({"ok": True})


